const BASE = new URL('./', self.location.href);
const ROOT = new URL('../../../../', BASE);
const PREFIX = 'gjh-v11:' + BASE.pathname + ':offline:';
const CACHE = PREFIX + BUILD;
const assets = new Map([...PRECACHE, ...LAZY_ASSETS].map(entry => [new URL(entry.path, BASE).pathname, entry]));
const offline = assets.get(new URL('offline.html', BASE).pathname);

// Embedded in each worker so its lifecycle and cache stay within its registration.
async function verifyResponse(response, {path, sha256}) {
  if (response?.status !== 200 || response.redirected) throw new Error('Unavailable resource: ' + path);
  const type = response.headers.get('Content-Type')?.split(';')[0].trim().toLowerCase();
  if ((path.endsWith('.css') && type !== 'text/css') ||
      (path.endsWith('.js') && !/^(?:text|application)\/(?:x-)?(?:java|ecma)script$/.test(type))) {
    throw new Error('Unexpected resource type: ' + path);
  }
  const bytes = await response.clone().arrayBuffer();
  if (!bytes.byteLength) throw new Error('Empty resource: ' + path);
  const digest = await crypto.subtle.digest('SHA-256', bytes);
  const actual = Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('');
  if (actual !== sha256) throw new Error('Integrity check failed: ' + path);
  return response;
}

async function cachedResource(entry, cacheName) {
  if (!entry) return;
  try {
    const response = await caches.match(new URL(entry.path, BASE), {cacheName});
    return await verifyResponse(response, entry);
  } catch { /* A missing, unreadable or invalid entry can be fetched again. */ }
}

async function fetchResource(entry, build) {
  const url = new URL(entry.path, BASE);
  url.searchParams.set('v', build);
  const response = await fetch(url, {cache: 'reload', credentials: 'omit', redirect: 'error'});
  return verifyResponse(response, entry);
}

async function precachedResource(entry, cacheName, build) {
  const cached = await cachedResource(entry, cacheName);
  if (cached) return cached;
  const response = await fetchResource(entry, build);
  try {
    const cache = await caches.open(cacheName);
    await cache.put(new URL(entry.path, BASE), response.clone());
  } catch { /* A verified network response is usable even if storage is unavailable. */ }
  return response;
}

async function preparePrecache(entries, cacheName, build, repair = false) {
  const cache = await caches.open(cacheName);
  // Bound memory and let every in-flight write settle before install cleanup.
  for (let offset = 0; offset < entries.length; offset += 6) {
    const results = await Promise.allSettled(entries.slice(offset, offset + 6).map(async entry => {
      if (repair && await cachedResource(entry, cacheName)) return;
      await cache.put(new URL(entry.path, BASE), await fetchResource(entry, build));
    }));
    const failure = results.find(result => result.status === 'rejected');
    if (failure) throw failure.reason;
  }
  // Read from storage again: a successful download alone does not verify the saved release.
  for (const entry of entries) {
    if (!await cachedResource(entry, cacheName)) throw new Error('Incomplete precache: ' + entry.path);
  }
}

async function activateVerified(entries, cacheName, build, port) {
  try {
    // Entries may be evicted while a fully installed worker waits for consent.
    await preparePrecache(entries, cacheName, build, true);
    await self.skipWaiting();
  } catch {
    port?.postMessage({type: 'UPDATE_FAILED'});
  }
}

function offlinePage() {
  return new Response('<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Connection needed</title><h1>Reconnect to continue</h1><p>Reload this page when you are back online.</p>',
    {headers: {'Content-Type': 'text/html; charset=utf-8'}});
}

async function installRelease() {
  try {
    const response = await fetch(new URL('version.json?v=' + BUILD, ROOT), {cache: 'reload', redirect: 'error'});
    if (!response.ok || response.redirected) throw new Error('Release identity unavailable');
    const identity = await response.json();
    if (identity.build !== BUILD || identity.version !== VERSION) throw new Error('Release identity mismatch');
    await preparePrecache(PRECACHE, CACHE, BUILD);
  } catch (error) {
    await caches.delete(CACHE);
    throw error;
  }
}

self.addEventListener('install', event => event.waitUntil(installRelease()));
self.addEventListener('activate', event => event.waitUntil((async () => {
  await Promise.all((await caches.keys()).filter(key => key.startsWith(PREFIX) && key !== CACHE).map(key => caches.delete(key)));
  await self.clients.claim();
})()));
self.addEventListener('message', event => {
  if (event.data?.type === 'GET_VERSION') event.ports[0]?.postMessage({version: VERSION, build: BUILD});
  if (event.data?.type === 'SKIP_WAITING') event.waitUntil(activateVerified(PRECACHE, CACHE, BUILD, event.ports[0]));
});
self.addEventListener('fetch', event => {
  const request = event.request, url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== BASE.origin || !url.pathname.startsWith(BASE.pathname)) return;

  const entry = assets.get(url.pathname);
  const recovery = request.mode === 'navigate' && url.searchParams.has('recover-page');
  const referrer = request.referrer?.startsWith(BASE.origin + '/') ? new URL(request.referrer) : null;
  if (request.mode !== 'navigate' && referrer?.origin === BASE.origin &&
      referrer.pathname.startsWith(BASE.pathname) && referrer.searchParams.has('recover-page')) {
    event.respondWith(fetch(request, {cache: 'reload'}));
  } else if (entry?.path.startsWith('assets/districts/') && !recovery && request.headers?.has('Range') && !request.headers.has('If-Range')) {
    // The cache stores verified complete files. Derive a requested byte range
    // from that full response without ever caching a partial model.
    event.respondWith((async () => {
      const match = /^bytes=(\d*)-(\d*)$/.exec(request.headers.get('Range'));
      if (!match || (!match[1] && !match[2])) return fetch(request);
      const response = await precachedResource(entry,CACHE,BUILD), data = await response.arrayBuffer();
      const size = data.byteLength;
      const first = match[1] ? Number(match[1]) : Math.max(0,size-Number(match[2]));
      const last = match[1] && match[2] ? Math.min(size-1,Number(match[2])) : size-1;
      if (first > last || first >= size) return new Response(null,{status:416,headers:{'Content-Range':'bytes */'+size}});
      return new Response(data.slice(first,last+1),{status:206,headers:{
        'Accept-Ranges':'bytes','Content-Range':`bytes ${first}-${last}/${size}`,
        'Content-Length':String(last-first+1),'Content-Type':response.headers.get('Content-Type') || 'application/octet-stream'}});
    })().catch(() => Response.error()));
  } else if (entry && !recovery) {
    event.respondWith(precachedResource(entry, CACHE, BUILD).catch(async () =>
      request.mode === 'navigate' ? await cachedResource(offline, CACHE) || offlinePage() : Response.error()));
  } else if (request.mode === 'navigate') {
    event.respondWith((async () => {
      // Reload the online document before clearing the active version's cache.
      const response = await fetch(request, {cache: recovery ? 'reload' : 'no-cache'});
      if (recovery && response.ok) await caches.delete(CACHE).catch(() => {});
      if (response.status === 404 && event.clientId) (await self.clients.get(event.clientId))?.postMessage({type: 'CHECK_FOR_UPDATE'});
      return response;
    })().catch(async () => await cachedResource(offline, CACHE) || offlinePage()));
  }
});
